{"explanation":"Latest-request causality: only the mounted request whose ID is current and loading may settle. New searches cancel the prior request first; disposal cancels and resets.","mapping":"State tracks mounted, query, current request ID, loading, result, and error. Each event produces post-event state plus only that event's effects.","assumptions":"Events use type search, success, failure, cancel, dispose, or mount. Result and error values may be any JSON value.","applies":"function applies(input){return !!input&&Array.isArray(input.events)}","holds":"function holds(input,output){if(!Array.isArray(output)||output.length!==input.events.length)return false; return output.every(function(o){return o&&typeof o==='object'&&['mounted','query','current','loading','result','error','effects'].every(function(k){return Object.prototype.hasOwnProperty.call(o,k)})&&Array.isArray(o.effects)})}","program":"function solve({config,state,event}){
  function fresh(m){return {mounted:m,query:'',current:null,loading:false,result:null,error:null}}
  var s=state||fresh(true), e=event||{}, fx=[];
  if(!s.mounted){
    if(e.type==='mount') s=fresh(true);
    return {state:s,output:{mounted:s.mounted,query:s.query,current:s.current,loading:s.loading,result:s.result,error:s.error,effects:fx}};
  }
  if(e.type==='search'){
    if(s.loading)fx.push({type:'cancel',id:s.current});
    s={mounted:true,query:e.query,current:e.id,loading:true,result:s.result,error:null};
    fx.push({type:'request',id:e.id,query:e.query});
  }else if(e.type==='success'){
    if(s.loading&&s.current===e.id){s={mounted:true,query:s.query,current:s.current,loading:false,result:e.result,error:null};}
  }else if(e.type==='failure'){
    if(s.loading&&s.current===e.id){s={mounted:true,query:s.query,current:s.current,loading:false,result:s.result,error:e.error};}
  }else if(e.type==='cancel'){
    if(s.loading){fx.push({type:'cancel',id:s.current});s={mounted:true,query:s.query,current:null,loading:false,result:s.result,error:null};}
  }else if(e.type==='dispose'){
    if(s.loading)fx.push({type:'cancel',id:s.current});
    s=fresh(false);
  }
  return {state:s,output:{mounted:s.mounted,query:s.query,current:s.current,loading:s.loading,result:s.result,error:s.error,effects:fx}};
}"}
